import{_ as e,d as a,e as o,y as r}from"./chunks/framework.D7CAgLCq.js";const f=JSON.parse('{"title":"受影响的位置要找到哪里","description":"必须列全的位置与更远影响的相称追踪分开，未知仍可能阻断采用。","frontmatter":{"title":"受影响的位置要找到哪里","description":"必须列全的位置与更远影响的相称追踪分开，未知仍可能阻断采用。"},"headers":[],"relativePath":"concepts/affected-positions.md","filePath":"concepts/affected-positions.md"}'),s={name:"concepts/affected-positions.md"};function p(d,t,i,n,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="受影响的位置要找到哪里" tabindex="-1">受影响的位置要找到哪里 <a class="header-anchor" href="#受影响的位置要找到哪里" aria-label="Permalink to &quot;受影响的位置要找到哪里&quot;">​</a></h1><p>必须列全的位置与更远影响的相称追踪分开，未知仍可能阻断采用。</p><p>间接和代际影响可以不断延伸。说“已经考虑所有人”而不说明界线，既无法核查，也让被遗漏者无从质疑。v2的<a href="./../theory/part-14.html#section-14-4-1">§14.4.1</a>给出两层识别责任。</p><p><strong>必须全部列出</strong>直接受影响位置、已知或经他人指出的低权力位置，以及应用模块要求单列的位置。其余位置沿声明通道与九轴追踪；损害越重、越不可逆、人数越多、越可能累积，位置权力越低，追踪就应越远。</p><p>继续追踪已不能合理改变判断、方案比较或保护安排时，可以停止，并公开界线、查过的通道、问过的位置和未知。他人指出新通道时，纳入或说明不采纳理由。不能让受益于较窄界线的一方独自定界：依据要事前公布，可以申诉；高影响或存在利益冲突时须独立复核。</p><div class="xk-table"><table><thead><tr><th>未知类型</th><th>对采用的影响</th></tr></thead><tbody><tr><td>有合理依据可能暴露保护失败或改变比较</td><td>阻断相应采用部分，补证、缩小方案或提供另有依据的保护</td></tr><tr><td>其余未知</td><td>如实登记，保留观察和重新识别条件</td></tr></tbody></table></div><p>教学情景：服务调整影响现有使用者，也已有人指出无证件者可能被漏掉。不能把后一位置丢进“间接影响太远”的箱子。遥远后果可按风险追踪，但不行动造成的既有损失也必须进入同一审查。</p><p>后来识别到的人拥有同等申诉、纠正和补救入口，不需先证明自己本来可被预见。识别范围的界线不会减轻已识别者的保护，也不能成为拖延已知伤害保护的理由。</p><p>继续阅读：<a href="./../theory/part-14.html#section-14-4">§14.4方案比较</a>、<a href="./../theory/part-14.html#section-14-8">§14.8保护</a>、<a href="./choices-with-loss.html">全有损失时的选择</a>。</p>',9)])])}const _=e(s,[["render",p]]);export{f as __pageData,_ as default};
